var DAY=86400000,MGOAL={stages:'কনসেপ্ট ধাপ সম্পন্ন',quiz:'কুইজ সম্পন্ন',games:'গেম খেলা',sims:'আলাদা সিমুলেশন',daily:'ডেইলি চ্যালেঞ্জ (দিন)',xp:'মোট XP',perfect:'পারফেক্ট কুইজ',review:'ভুলের খাতায় সঠিক রিভিশন'};
